import '../wing_enums.dart';

/// Payment to authorize. `rand_str` and `timestamp` are generated by the
/// SDK; every optional field is sent only when set.
class WingPayment {
  /// your unique order id (`order_reference_no`)
  final String orderReferenceNo;

  /// amount to pay, at most 2 decimals; sent as `15.00` in USD or KHR
  final num amount;

  /// Wing redirects the payer here (GET) after paying, with
  /// `?status=success&token=...`
  final String returnUrl;

  /// Wing redirects the payer here (GET) when they cancel
  final String cancelUrl;

  /// [WingIntegrationType.webApp] (default) or
  /// [WingIntegrationType.mobileApp] for the deep link back to your app
  final WingIntegrationType integrationType;

  /// whether the Wing Bank app is installed on the payer's phone
  /// (`is_wingapp_installed`)
  final bool isWingAppInstalled;

  /// remark of the product or item, max 255 characters
  final String? itemName;

  /// name shown to the payer; Wing shows your registered name without it
  final String? merchantName;

  /// Wing account filled in for the payer
  final String? wingAccount;

  /// Creates a [WingPayment].
  const WingPayment({
    required this.orderReferenceNo,
    required this.amount,
    required this.returnUrl,
    required this.cancelUrl,
    this.integrationType = WingIntegrationType.webApp,
    this.isWingAppInstalled = false,
    this.itemName,
    this.merchantName,
    this.wingAccount,
  });

  @override
  String toString() =>
      'WingPayment(orderReferenceNo: $orderReferenceNo, amount: $amount, '
      'integrationType: ${integrationType.value})';
}
